Rules.InvariantScript:
If(
    IsBlank(TextInput1.Text) Or
    IsBlank(NumberInput2.Value) Or NumberInput2.Value < 1,
    Notify("Please fill in all fields", NotificationType.Error),
    Patch(
        Beaches,
        LookUp(Beaches, 'Beach Names' = varBeach.Title),
        {
            'Number Of Volunteers': NumberInput2.Value,
            'Alert Reason': TextInput1.Text
        }
    );
    Notify("Volunteer requirement saved for your beach.", NotificationType.Success);
    Navigate('Raised Alert')
)
